let body = $input.first().json.body ?? $input.first().json ?? {};
if (Array.isArray(body)) body = body[0] || {};

const s = v => (v === undefined || v === null) ? '' : String(v).trim();

const pageType = s(body.pageType).toLowerCase();
if (!['industry', 'solution'].includes(pageType)) {
  throw new Error(`pageType is required and must be "industry" or "solution". Received: "${s(body.pageType)}"`);
}
if (!s(body.h1)) {
  throw new Error('h1 is required. It is used verbatim as the page H1 and is never rewritten.');
}
if (!s(body.coreKeyword)) {
  throw new Error('coreKeyword is required.');
}
if (!s(body.clientName)) {
  throw new Error('clientName is required. The page names the client throughout and the meta description has to open with it.');
}
if (!s(body.productDescription)) {
  throw new Error('productDescription is required. With no page angle supplied, it is what the Writer derives the angle from.');
}

return [{ json: {
  taskId: s(body.taskId),
  brandId: s(body.brandId),
  userId: s(body.userId),
  callback_url: s(body.callback_url),

  pageType,
  h1: s(body.h1),
  coreKeyword: s(body.coreKeyword),
  secondaryKeywords: s(body.secondaryKeywords),
  targetLanguage: s(body.targetLanguage) || 'English',

  industry: s(body.industry),

  clientName: s(body.clientName),
  productDescription: s(body.productDescription),
  clientProof: s(body.clientProof),
  certifications: s(body.certifications),

  writingPreferences: s(body.writingPreferences),

  researchEnabled: body.researchEnabled === true || String(body.researchEnabled).toLowerCase() === 'true',

  whitelistDomains: body.whitelistDomains ?? [],
  blacklistDomains: body.blacklistDomains ?? [],

  pineconeIndex: s(body.pineconeIndex),
  pineconeNamespace: s(body.pineconeNamespace)
} }];

