const languageKey = String(req.targetLanguage || 'English').toLowerCase().trim();
const targetSource = LANGUAGE_MAP[languageKey];

if (!targetSource) {
  throw new Error(`Unsupported targetLanguage: "${req.targetLanguage}". Must be one of the languages supported by DeepL (e.g. "Spanish", "German", "Japanese").`);
}

const targetCountry = LANGUAGE_TO_COUNTRY[languageKey] || '';

const MAX_DOMAINS = 30;
const DEFAULT_BLACKLIST = 'wikipedia.org';

const cleanDomain = (val) => {
  const match = String(val).match(/\[([^\]]+)\]\([^)]+\)/);
  return match ? match[1] : String(val);
};
const toList = v => Array.isArray(v) ? v : String(v || '').split(',');

const whitelistArray = toList(req.whitelistDomains)
  .map(d => cleanDomain(String(d).trim())).filter(Boolean).slice(0, MAX_DOMAINS);

let blacklistArray = toList(req.blacklistDomains)
  .map(d => cleanDomain(String(d).trim())).filter(Boolean).slice(0, MAX_DOMAINS);

if (blacklistArray.length === 0) blacklistArray = [DEFAULT_BLACKLIST];

const whitelistFields = {};
for (let i = 0; i < MAX_DOMAINS; i++) whitelistFields[`whiteLink${i + 1}`] = whitelistArray[i] || '';
const blacklistFields = {};
for (let i = 0; i < MAX_DOMAINS; i++) blacklistFields[`blackLink${i + 1}`] = blacklistArray[i] || '';

return [{ json: {
  targetLanguage: req.targetLanguage || 'English',
  targetSource,
  targetCountry,
  pageType: req.pageType,
  h1: req.h1,
  coreKeyword: req.coreKeyword,
  secondaryKeywords: req.secondaryKeywords,
  industry: req.industry,
  clientName: req.clientName,
  productDescription: req.productDescription,
  clientProof: req.clientProof,
  certifications: req.certifications,
  writingPreferences: req.writingPreferences,
  researchEnabled: req.researchEnabled,
  ...whitelistFields,
  ...blacklistFields,
  whitelistCount: whitelistArray.length,
  blacklistCount: blacklistArray.length,
  route: item.route || ''
} }];

const brief = $('Brief Parser').first().json;
const req = $('request-parser').first().json;

const candidates = [
  ['h1', brief.h1], ['coreKeyword', brief.coreKeyword], ['secondaryKeywords', brief.secondaryKeywords],
  ['industry', brief.industry],
  ['productDescription', brief.productDescription], ['clientProof', brief.clientProof],
  ['certifications', brief.certifications], ['writingPreferences', brief.writingPreferences]
];

const fields = candidates.filter(([n, v]) => v && String(v).trim().length > 0);

return [{ json: {
  fieldNames: fields.map(f => f[0]),
  fieldTexts: fields.map(f => String(f[1])),
  targetSource: brief.targetSource
} }];

const route = $('Route Classifier').first().json.route;
const brief = $('Brief Parser').first().json;
const j = $input.first().json;

const tr = {};
if (j.translations) {
  const names = $('DeepL Prep').first().json.fieldNames;
  if (!Array.isArray(j.translations) || j.translations.length !== names.length) {
    throw new Error(`DeepL returned ${j.translations?.length} translations but expected ${names.length}`);
  }
  names.forEach((n, i) => { tr[n] = j.translations[i].text; });
}

return [{ json: {
  ...brief,
  route,
  isIndustry: route.startsWith('industry'),
  isLang: route.endsWith('_lang'),

  // the H1 the client supplied, in their language. Restored onto the page after localisation.
  originalH1: brief.h1,
  originalCoreKeyword: brief.coreKeyword,
  originalSecondaryKeywords: brief.secondaryKeywords,

  h1:                 tr.h1 ?? brief.h1,
  coreKeyword:        tr.coreKeyword ?? brief.coreKeyword,
  secondaryKeywords:  tr.secondaryKeywords ?? brief.secondaryKeywords,
  industry:           tr.industry ?? brief.industry,
  productDescription: tr.productDescription ?? brief.productDescription,
  clientProof:        tr.clientProof ?? brief.clientProof,
  certifications:     tr.certifications ?? brief.certifications,
  writingPreferences: tr.writingPreferences ?? brief.writingPreferences
} }];
